def transform(grid):
    h, w = len(grid), len(grid[0])
    pts = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 7]
    r0 = min(r for r, c in pts)
    c0 = min(c for r, c in pts)
    shape = {(r-r0, c-c0) for r, c in pts}
    out = [row[:] for row in grid]
    for dr in range(h - max(r for r, c in shape)):
        for dc in range(w - max(c for r, c in shape)):
            cells = [(dr+r, dc+c) for r, c in shape]
            if (dr, dc) != (r0, c0) and all(grid[r][c] == 0 for r, c in cells):
                for r, c in cells:
                    out[r][c] = 7
    return out
